<script setup lang="ts">
import {nextTick,ref,watch} from 'vue'
import {Search,ChevronUp,ChevronDown,X} from 'lucide-vue-next'
const props=defineProps<{show:boolean;query:string;count:number;index:number;target:string;regex:boolean;caseSensitive:boolean;replacement:string;replaceOpen:boolean;error:string}>()
const emit=defineEmits<{'update:query':[value:string];'update:regex':[value:boolean];'update:caseSensitive':[value:boolean];'update:replacement':[value:string];'update:replaceOpen':[value:boolean];replace:[all:boolean];step:[delta:number];close:[]}>()
const input=ref<HTMLInputElement>()
watch(()=>props.show,async show=>{if(show){await nextTick();input.value?.focus();input.value?.select()}},{immediate:true})
function focus(){input.value?.focus();input.value?.select()}
defineExpose({focus})
</script>
<template><div v-if="show" class="note-find-bar" role="search" aria-label="页面内检索"><div class="find-row"><button class="icon-button" aria-label="展开或收起替换" :aria-expanded="replaceOpen" @click="emit('update:replaceOpen',!replaceOpen)"><ChevronDown :size="15"/></button><Search :size="16"/><input ref="input" :value="query" aria-label="页面内查找内容" :placeholder="'在'+target+'中查找…'" @input="emit('update:query',($event.target as HTMLInputElement).value)" @keydown.enter.prevent="emit('step',$event.shiftKey?-1:1)" @keydown.esc.prevent.stop="emit('close')"/><button class="option" :class="{active:caseSensitive}" aria-label="区分大小写" :aria-pressed="caseSensitive" @click="emit('update:caseSensitive',!caseSensitive)">Aa</button><button class="option" :class="{active:regex}" aria-label="正则表达式" :aria-pressed="regex" @click="emit('update:regex',!regex)">.*</button><span class="note-find-count">{{query?(count?`${index+1} / ${count}`:'无匹配'):'查找'}}</span><button class="icon-button" aria-label="上一个匹配" :disabled="!count||!!error" @click="emit('step',-1)"><ChevronUp :size="16"/></button><button class="icon-button" aria-label="下一个匹配" :disabled="!count||!!error" @click="emit('step',1)"><ChevronDown :size="16"/></button><button class="icon-button" aria-label="关闭页面内检索" @click="emit('close')"><X :size="15"/></button></div><div v-if="replaceOpen" class="find-row"><input :value="replacement" aria-label="页面内替换内容" placeholder="替换为…（留空则删除匹配）" @input="emit('update:replacement',($event.target as HTMLInputElement).value)" @keydown.enter.prevent="emit('replace',false)"/><button class="option" :disabled="!count||!!error" @click="emit('replace',false)">替换</button><button class="option" :disabled="!count||!!error" @click="emit('replace',true)">全部替换</button></div><small v-if="replaceOpen">替换 Markdown 原文，保留当前视图。<template v-if="regex">支持 $1、$&lt;名称&gt; 捕获组。</template></small><small v-if="error" class="error" role="alert">{{error}}</small></div></template>
<style scoped>.note-find-bar{padding:8px 11px;border:1px solid var(--line);border-radius:8px;background:var(--bg);box-shadow:var(--shadow);width:min(570px,calc(100% - 24px));box-sizing:border-box;position:absolute;right:12px;top:8px;z-index:20;color:var(--muted)}.find-row{display:flex;align-items:center;gap:6px}.find-row+ .find-row{border-top:1px solid var(--line);margin-top:5px;padding-top:5px}input{flex:1;min-width:40px;border:0;outline:0;background:transparent;color:var(--text);font:inherit;font-size:.85rem;padding:5px 0}.note-find-bar:focus-within{border-color:var(--accent)}.note-find-count{white-space:nowrap;font-size:.75rem;min-width:42px;text-align:center}.option{border:1px solid var(--line);border-radius:4px;padding:3px 6px;background:transparent;color:var(--text);white-space:nowrap;cursor:pointer}.option.active{background:var(--accent);color:white}.option:disabled{opacity:.4;cursor:default}small{display:block;margin-top:5px;font-size:.72rem}.error{color:#d03050}</style>
